ssize_t device_write(struct file *filp, const char __user *buf, size_t count, loff_t *fpos) {
    struct device *dev = filp->private_data;
    struct element_info *info = NULL;
    ssize_t bytes_written = 0;
    int ret = 0;

    if (!dev) {
        return -EINVAL;
    }

    if (!dev->is_connected) {
        return -ENODEV;
    }

    info = kmalloc(sizeof(struct element_info), GFP_KERNEL);
    if (!info) {
        return -ENOMEM;
    }

    ret = prepare_data_for_writing(dev, info);
    if (ret < 0) {
        kfree(info);
        return ret;
    }

    if (count > dev->max_write_size) {
        count = dev->max_write_size;
    }

    if (copy_from_user(info->data, buf, count)) {
        kfree(info);
        return -EFAULT;
    }

    info->length = count;

    ret = update_sequence_number(dev, info);
    if (ret < 0) {
        kfree(info);
        return ret;
    }

    ret = queue_element_for_processing(dev, info);
    if (ret < 0) {
        kfree(info);
        return ret;
    }

    bytes_written = count;

    release_device_reference(dev);

    return bytes_written;
}
